-- E09: bind the incumbent presentation readers to the canonical active client
-- relationship. Generated by the Supabase CLI and ordered above the verified
-- production/pending frontier while still empty and unapplied.
-- This does not activate external joins, loosen unique linkage, grant staff
-- customer identity, or remediate the remaining legacy/raw client consumers.

CREATE OR REPLACE FUNCTION public.get_client_portal_brand()
RETURNS TABLE(
  tenant_id uuid, tenant_name text, tenant_slug text, logo_url text, primary_color text,
  logo_dark_url text, favicon_url text, accent_color text, font text, tagline text,
  product_name text, from_name text, support_email text
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  WITH me AS (
    SELECT c.tenant_id AS tid
    FROM public.clients c
    WHERE c.id = public.client_portal_relationship_id()
  )
  SELECT
    rb.tenant_id, rb.tenant_name, rb.tenant_slug,
    COALESCE(rb.logo_url, p.brand_logo_url) AS logo_url,
    rb.primary_color,
    rb.logo_dark_url, rb.favicon_url, rb.accent_color, rb.font, rb.tagline,
    rb.product_name, rb.from_name, rb.support_email
  FROM me
  JOIN public.resolve_tenant_brand(me.tid) rb ON TRUE
  LEFT JOIN public.tenant_legal_profile p ON p.tenant_id = me.tid;
$$;
REVOKE ALL ON FUNCTION public.get_client_portal_brand() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_client_portal_brand() TO authenticated;

CREATE OR REPLACE FUNCTION public.get_client_portal_config()
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  WITH me AS (
    SELECT c.tenant_id AS tid
    FROM public.clients c
    WHERE c.id = public.client_portal_relationship_id()
  )
  SELECT COALESCE(
    (SELECT COALESCE(t.features->'portal_config', '{}'::jsonb)
     FROM public.tenants t
     JOIN me ON me.tid = t.id),
    '{}'::jsonb
  );
$$;
REVOKE ALL ON FUNCTION public.get_client_portal_config() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_client_portal_config() TO authenticated;

COMMENT ON FUNCTION public.get_client_portal_brand() IS
  'Existing brand cascade/return ABI, scoped through the Auth-bound active unmerged client relationship. No oldest-row, email, route or staff fallback.';
COMMENT ON FUNCTION public.get_client_portal_config() IS
  'Presentation-only overlay from the canonical active client relationship. Ambiguous relationships refuse; this overlay never grants module/record authority.';
